const HEAD = 'the wet-wall yield trend (v0.976.186)'
const SWING = HEAD + ": the yield's own swing - "
const SWING_TAIL = ' - the rise and the fall traded seats between the faces ' + TAIL
const SWELL = HEAD + ": the yield's rise ran two steps deep - "
const SWELL_TAIL = " - the yield's own swell " + TAIL
const FADE = HEAD + ": the yield's fall ran two steps deep - "
const FADE_TAIL = " - the yield's own fade " + TAIL

// THE FIELD'S OWN TABLE - the priced field 348..386 (the yield RE's
// own arithmetic, THIRTY-NINE faces deep) - THE CELL'S OWN WEIGHT
// 126u the faces' own total, THE FIELD'S OWN TOP THE COUNT 17 rode
// ONCE (the face 366's own crest - THE WALL'S OWN STORM), THE
// FIELD'S OWN FLOOR THE COUNT ZERO rode THREE times (the faces
// 355/359/377's own floors - THE TRIPLE DROUGHT)
const P = {}
P[348] = 1
P[349] = 2
P[350] = 4
P[351] = 2
P[352] = 2
P[353] = 3
P[354] = 6
P[355] = 0
P[356] = 4
P[357] = 5
P[358] = 6
P[359] = 0
P[360] = 2
P[361] = 7
P[362] = 4
P[363] = 3
P[364] = 2
P[365] = 1
P[366] = 17
P[367] = 2
P[368] = 5
P[369] = 1
P[370] = 1
P[371] = 4
P[372] = 4
P[373] = 5
P[374] = 2
P[375] = 1
P[376] = 4
P[377] = 0
P[378] = 7
P[379] = 2
P[380] = 2
P[381] = 6
P[382] = 3
P[383] = 1
P[384] = 1
P[385] = 3
P[386] = 1
let fieldSum = 0
for (let f = 348; f <= 386; f++) fieldSum += P[f]
assert.equal(fieldSum, 126, "the cell 126u the hand-off holds - THE WATER'S WALL FRONT'S OWN YIELD SEAT rides")
const w = (f) => wetWallYieldTrendRow({ back: { wetWallYields: P[f - 2] }, prev: { wetWallYields: P[f - 1] }, cur: { wetWallYields: P[f] } })

// the window's own shape - ONE SHAPE ONE WORD (the branch law: the
// bars never invent - a held step no direction, the honest silence)
const tallyWindow = (f, T) => {
  const a = T[f - 2], b = T[f - 1], c = T[f]
  const first = b - a, second = c - b
  if (first === 0 || second === 0) return 'silence'
  if (first > 0 && second > 0) return 'swell'
  if (first < 0 && second < 0) return 'fade'
  return 'swing'
}

// THE FIELD'S OWN CHAINS - the priced windows the hand's own
// classification (SEVENTEEN swings, FIVE swells, FIVE fades, the TEN
// honest silences - TWENTY-SEVEN of THIRTY-SEVEN speaking)
const SWELLS = {
  350: '1 -> 2 (+1) -> 4 (+2)',
  354: '2 -> 3 (+1) -> 6 (+3)',
  357: '0 -> 4 (+4) -> 5 (+1)',
  358: '4 -> 5 (+1) -> 6 (+1)',
  361: '0 -> 2 (+2) -> 7 (+5)'
}
const FADES = {
  363: '7 -> 4 (-3) -> 3 (-1)',
  364: '4 -> 3 (-1) -> 2 (-1)',
  365: '3 -> 2 (-1) -> 1 (-1)',
  375: '5 -> 2 (-3) -> 1 (-1)',
  383: '6 -> 3 (-3) -> 1 (-2)'
}
const SWINGS = {
  351: '2 -> 4 (+2) -> 2 (-2)',
  355: '3 -> 6 (+3) -> 0 (-6)',
  356: '6 -> 0 (-6) -> 4 (+4)',
  359: '5 -> 6 (+1) -> 0 (-6)',
  360: '6 -> 0 (-6) -> 2 (+2)',
  362: '2 -> 7 (+5) -> 4 (-3)',
  366: '2 -> 1 (-1) -> 17 (+16)',
  367: '1 -> 17 (+16) -> 2 (-15)',
  368: '17 -> 2 (-15) -> 5 (+3)',
  369: '2 -> 5 (+3) -> 1 (-4)',
  374: '4 -> 5 (+1) -> 2 (-3)',
  376: '2 -> 1 (-1) -> 4 (+3)',
  377: '1 -> 4 (+3) -> 0 (-4)',
  378: '4 -> 0 (-4) -> 7 (+7)',
  379: '0 -> 7 (+7) -> 2 (-5)',
  382: '2 -> 6 (+4) -> 3 (-3)',
  386: '1 -> 3 (+2) -> 1 (-2)'
}
const tally = { swing: 0, swell: 0, fade: 0, silence: 0 }
for (let f = 350; f <= 386; f++) tally[tallyWindow(f, P)]++
assert.deepEqual(tally, { swing: 17, swell: 5, fade: 5, silence: 10 }, "the birth field's own breath the THIRTY-SEVEN windows hold - TWENTY-SEVEN speaking")
assert.equal(tally.swing, 17, 'SEVENTEEN swings the churn\u2019s own mass rides')
for (const [f, arc] of Object.entries(SWELLS)) {
  assert.equal(w(Number(f)), SWELL + arc + SWELL_TAIL, `the swell F${f} the arc rides`)
}
for (const [f, arc] of Object.entries(FADES)) {
  assert.equal(w(Number(f)), FADE + arc + FADE_TAIL, `the fade F${f} the arc rides`)
}
for (const [f, arc] of Object.entries(SWINGS)) {
  assert.equal(w(Number(f)), SWING + arc + SWING_TAIL, `the swing F${f} the arc rides`)
}
for (const f of [352, 353, 370, 371, 372, 373, 380, 381, 384, 385]) {
  assert.equal(w(f), null, `the silence F${f} the held law keeps - the row never invents`)
}

// THE QUAD SILENCE RUN - the faces 370..373's own four the longest
// drought this book holds (the .185's own one silence run the faces
// 360..363 hold - the same four-window weight the mirror rides)
const silenceRun = []
let run = []
for (let f = 350; f <= 386; f++) {
  if (tallyWindow(f, P) === 'silence') run.push(f)
  else { if (run.length > silenceRun.length) silenceRun.splice(0, silenceRun.length, ...run); run = [] }
}
if (run.length > silenceRun.length) silenceRun.splice(0, silenceRun.length, ...run)
assert.deepEqual(silenceRun, [370, 371, 372, 373], 'the QUAD silence run the faces 370..373 hold - the longest drought the book rides')

// THE TRIPLE BACK-TO-BACK FADE RUN - the faces 363/364/365's own
// windows every one descending (the drought's own staircase rides -
// the fade pairs the run's own joints hold) - and the ONE
// back-to-back swell pair the faces 357/358 hold (the bprep's own
// ONE pair the mirror beside)
const swellPairs = []
for (let f = 351; f <= 386; f++) {
  if (tallyWindow(f, P) === 'swell' && tallyWindow(f - 1, P) === 'swell') swellPairs.push([f - 1, f])
}
assert.deepEqual(swellPairs, [[357, 358]], 'the ONE back-to-back swell pair the faces 357/358 hold - the mirror rides')
const fadePairs = []
for (let f = 351; f <= 386; f++) {
  if (tallyWindow(f, P) === 'fade' && tallyWindow(f - 1, P) === 'fade') fadePairs.push([f - 1, f])
}
assert.deepEqual(fadePairs, [[363, 364], [364, 365]], 'the TWO fade pairs the TRIPLE run\u2019s own joints hold')
for (let i = 1; i < fadePairs.length; i++) {
  assert.equal(fadePairs[i][0] - fadePairs[i - 1][0], 1, 'the fade pairs back-to-back the TRIPLE run rides - no gap the staircase holds')
}

// THE TWO ROUND TRIPS - the faces 351/386's own windows the mirrored
// legs ride (never back-to-back - the whole field's own spread the
// book holds)
const roundTrips = []
for (let f = 350; f <= 386; f++) {
  if (P[f - 2] === P[f] && !(P[f - 1] === P[f - 2] || P[f] === P[f - 1])) roundTrips.push(f)
}
assert.deepEqual(roundTrips, [351, 386], 'the birth field holds the TWO round trips - the mirrored legs ride')
assert.equal(roundTrips[1] - roundTrips[0], 35, 'the round trips never back-to-back the spread holds')
for (const f of roundTrips) {
  assert.equal(Math.abs(P[f - 1] - P[f - 2]), Math.abs(P[f] - P[f - 1]), `the round trip F${f} the same size both legs the mirror rides`)
}
assert.equal(w(351), SWING + '2 -> 4 (+2) -> 2 (-2)' + SWING_TAIL, 'the opener\u2019s own round trip the swing rides')
assert.equal(w(386), SWING + '1 -> 3 (+2) -> 1 (-2)' + SWING_TAIL, 'the closer\u2019s own round trip the swing rides')

// THE TOP THE COUNT 17 - rode ONCE the face 366's own crest holds
// (THE WALL'S OWN STORM the book holds)
assert.equal(Math.max(...Object.values(P)), 17, 'the birth top the count 17 the wall storm rides')
let topRode = 0
const topFaces = []
for (let f = 348; f <= 386; f++) { if (P[f] === 17) { topRode++; topFaces.push(f) } }
assert.equal(topRode, 1, 'the top rode ONCE the one crest holds')
assert.deepEqual(topFaces, [366], 'the face 366 the crest\u2019s own seat rides')

// THE TRIPLE DROUGHT - the zero faces the faces 355/359/377's own
// floors hold (the bfcu's own thirty-seven the heaviest drought
// record the family holds beside)
const zeroFaces = []
for (let f = 348; f <= 386; f++) { if (P[f] === 0) zeroFaces.push(f) }
assert.equal(zeroFaces.length, 3, 'THE TRIPLE DROUGHT the three zero faces ride')
assert.deepEqual(zeroFaces, [355, 359, 377], 'the faces 355/359/377 the floors\u2019 own seats ride')

// THE BOUNDS - the +16 the max rise rode TWICE two legs ONE boundary
// (the boundary 365/366 the windows 366/367 share - THE CREST'S OWN
// CLIMB), the -15 the max fall rode TWICE two legs ONE boundary (the
// boundary 366/367 the windows 367/368 share - THE CRATER'S OWN
// DRAIN the crest 17 the floor 2)
const steps = []
for (let f = 350; f <= 386; f++) { steps.push(P[f - 1] - P[f - 2]); steps.push(P[f] - P[f - 1]) }
assert.equal(Math.max(...steps), 16, 'the birth max rise +16 the bound holds')
assert.equal(Math.min(...steps), -15, 'the birth max fall -15 the bound holds')
assert.equal(steps.filter(s => s === 16).length, 2, 'the +16 rode TWICE two legs the crest\u2019s own climb holds')
assert.equal(steps.filter(s => s === -15).length, 2, 'the -15 rode TWICE two legs the crater\u2019s own drain holds')
assert.equal(P[366] - P[365], 16, 'the crest\u2019s own climb the boundary 365/366 rides')
assert.equal(P[367] - P[366], -15, 'the crater\u2019s own drain the boundary 366/367 rides - the crest 17 the floor 2')

// THE LAST WORD - the face 386's own window the swing (the round
// trip the closer holds)
assert.equal(w(386), SWING + '1 -> 3 (+2) -> 1 (-2)' + SWING_TAIL, 'the last word the swing rides')

// THE WHOLE-CACHE SEAT 161u - the face 425's own 6u the newest add
// rides (the W425 window the swing the nearest-completed law holds -
// the cancelled 424 the honest gap rides; the face 422's own 7u the
// mirror beside; the W389 window the swing the post field holds)
const E = {}
E[387] = 2
E[388] = 0
E[389] = 7
E[417] = 3
E[418] = 6
E[420] = 0
E[421] = 1
E[422] = 7
E[423] = 3
E[425] = 6
let postSum = 0
for (const f of [387, 388, 389, 417, 418, 420, 421, 422, 423, 425]) postSum += E[f]
assert.equal(126 + postSum, 161, "the whole-cache 161u the face 425's own 6u the newest add rides")
assert.equal(E[425], 6, "the face 425's own 6u the wet-wall yield lines the read byte-true holds")
assert.equal(E[422], 7, "the face 422's own 7u the mirror beside rides")
const ew = (f, T) => wetWallYieldTrendRow({ back: { wetWallYields: T[f - 2] }, prev: { wetWallYields: T[f - 1] }, cur: { wetWallYields: T[f] } })
// the W425 window the nearest-completed law holds (the face 424 the
// honest gap rides - the cancelled run no face) - the triple built
// whole: back 422, prev 423, cur 425
assert.equal(wetWallYieldTrendRow({ back: { wetWallYields: E[422] }, prev: { wetWallYields: E[423] }, cur: { wetWallYields: E[425] } }), SWING + '7 -> 3 (-4) -> 6 (+3)' + SWING_TAIL, 'the W425 window the swing rides - MY WORD\u2019S OWN FIRST LIVE READ the nearest-completed law holds')
assert.equal(ew(389, E), SWING + '2 -> 0 (-2) -> 7 (+7)' + SWING_TAIL, 'the W389 window the swing rides')
assert.equal(ew(422, E), SWELL + '0 -> 1 (+1) -> 7 (+6)' + SWELL_TAIL, 'the W422 swell the post window rides')
assert.equal(ew(423, E), SWING + '1 -> 7 (+6) -> 3 (-4)' + SWING_TAIL, 'the W423 swing the post window rides')

// THE BYTE-PIN BATTERY - the three shapes the branch law prices
assert.equal(wetWallYieldTrendRow({ back: { wetWallYields: 1 }, prev: { wetWallYields: 2 }, cur: { wetWallYields: 3 } }), SWELL + '1 -> 2 (+1) -> 3 (+1)' + SWELL_TAIL)
assert.equal(wetWallYieldTrendRow({ back: { wetWallYields: 3 }, prev: { wetWallYields: 2 }, cur: { wetWallYields: 1 } }), FADE + '3 -> 2 (-1) -> 1 (-1)' + FADE_TAIL)
assert.equal(wetWallYieldTrendRow({ back: { wetWallYields: 1 }, prev: { wetWallYields: 3 }, cur: { wetWallYields: 2 } }), SWING + '1 -> 3 (+2) -> 2 (-1)' + SWING_TAIL)
// the honest silences the held law prices (a held step no direction)
assert.equal(wetWallYieldTrendRow({ back: { wetWallYields: 2 }, prev: { wetWallYields: 2 }, cur: { wetWallYields: 3 } }), null)
assert.equal(wetWallYieldTrendRow({ back: { wetWallYields: 2 }, prev: { wetWallYields: 3 }, cur: { wetWallYields: 3 } }), null)
// the zero a lawful count - the zeros ride the rows whole (the
// triple drought's own floors the whole field's own lawful counts)
assert.equal(wetWallYieldTrendRow({ back: { wetWallYields: 0 }, prev: { wetWallYields: 1 }, cur: { wetWallYields: 0 } }), SWING + '0 -> 1 (+1) -> 0 (-1)' + SWING_TAIL)
assert.equal(wetWallYieldTrendRow({ back: { wetWallYields: 0 }, prev: { wetWallYields: 0 }, cur: { wetWallYields: 0 } }), null)

// THE FENCE BATTERY - the fold that cannot prove itself prices
// nothing (the fence law: the word never rides a lie)
assert.equal(wetWallYieldTrendRow(null), null)
assert.equal(wetWallYieldTrendRow(undefined), null)
assert.equal(wetWallYieldTrendRow('junk'), null)
assert.equal(wetWallYieldTrendRow(42), null)
assert.equal(wetWallYieldTrendRow([]), null)
assert.equal(wetWallYieldTrendRow({}), null)
assert.equal(wetWallYieldTrendRow({ back: { wetWallYields: 1 }, prev: { wetWallYields: 2 } }), null)
assert.equal(wetWallYieldTrendRow({ back: { wetWallYields: 1 }, cur: { wetWallYields: 2 } }), null)
assert.equal(wetWallYieldTrendRow({ prev: { wetWallYields: 1 }, cur: { wetWallYields: 2 } }), null)
assert.equal(wetWallYieldTrendRow({ back: { wetWallYields: 1 }, prev: { wetWallYields: 2 }, cur: { wetWallYields: -1 } }), null)
assert.equal(wetWallYieldTrendRow({ back: { wetWallYields: 1.5 }, prev: { wetWallYields: 2 }, cur: { wetWallYields: 3 } }), null)
assert.equal(wetWallYieldTrendRow({ back: { other: 1 }, prev: { wetWallYields: 2 }, cur: { wetWallYields: 3 } }), null)
assert.equal(wetWallYieldTrendConsistent({ back: { wetWallYields: 0 }, prev: { wetWallYields: 0 }, cur: { wetWallYields: 0 } }), true)
assert.equal(wetWallYieldTrendConsistent({ back: { wetWallYields: 5 }, prev: { wetWallYields: 9 }, cur: { wetWallYields: 2 }, spare: true }), true)
assert.equal(wetWallYieldTrendConsistent(null), false)
assert.equal(wetWallYieldTrendConsistent(undefined), false)
assert.equal(wetWallYieldTrendConsistent('junk'), false)
assert.equal(wetWallYieldTrendConsistent([]), false)
assert.equal(wetWallYieldTrendConsistent({ back: { wetWallYields: 1 }, prev: { wetWallYields: 2 }, cur: { wetWallYields: NaN } }), false)

// THE CELL'S OWN READ - the real yield lines ride (the tagged voice
// the climb lane prints only - every line the shape prints rides, no
// exclusion the shape needs)
assert.equal(wetWallYields([
  'F9 [F9] climb wet-wall yield: 4 wet rotations vs 0 dry at y=33 - no dry bearing owns this column, the fence reserve returns to the chain',
  'F19 [F19] climb wet-wall yield: 4 wet rotations vs 0 dry at y=59 - no dry bearing owns this column, the fence reserve returns to the chain',
  'F12 [F12] climb wet-wall yield: 2 wet rotations vs 3 dry at y=45 - no dry bearing owns this column, the fence reserve returns to the chain'
]), 3)
assert.equal(wetWallYields([
  'F17 [F17] climb wet-wall yield: 3 wet rotations vs 1 dry at y=41 - no dry bearing owns this column, the fence reserve returns to the chain'
]), 1)
// THE WRITE-OFF WHYS line's own wet-wall why token never rides - the
// write-off lane's own seat (the pocket's own census prices it)
assert.equal(wetWallYields(["write-off whys: wet-wall carries 569u of 1056u (53.9%) - the water's wall is the front"]), 0)
// the final write-off line's own why tokens never ride
assert.equal(wetWallYields(['final write-off: F8 273u/26s wet-wall, F11 214u/20s wet-wall, F4 151u/15s stalled-s0']), 0)
// the climb wet ascend lines the climbwet's own book prices never
// ride - the ascend lane's own seat (the lanes never merge)
assert.equal(wetWallYields(['F3 [F3] climb wet ascend: dug the ceiling stone at [-116,67,407] (the water column owns every bearing - the vertical digs instead, 2/3)']), 0)
// the repeat wet page lines the same-cell wet's own trend prices
// never ride
assert.equal(wetWallYields(['F8 water: repeat wet page at the same cell']), 0)
// the other lanes' lines never ride - the lanes never merge
assert.equal(wetWallYields(['F5 fuel anchor scan: the palette read empty x1 - the singular probe rescued the scan (chest at [-118,81,408])']), 0)
assert.equal(wetWallYields(['F5 final bank: 3 stacks deposited']), 0)
assert.equal(wetWallYields(['F2 bank: deposit done (128 items)']), 0)
// the bare skin never rides - no such emitter voice (the climb lane
// prints the tagged form only)
assert.equal(wetWallYields(['F6 climb wet-wall yield: 4 wet rotations vs 0 dry at y=33 - no dry bearing owns this column, the fence reserve returns to the chain']), 0)
// the no-shape junk line never rides - the shape's own proof the RE
// demands
assert.equal(wetWallYields(['F6 [F6] climb wet-wall yield 4 wet rotations vs 0 dry']), 0)
assert.equal(wetWallYields(['F6 [F6] climb wet-wall yields: 4 wet rotations vs 0 dry']), 0)
assert.equal(wetWallYields(['F6 [F6] climb wet-wall yield:']), 0)
assert.equal(wetWallYields(['climb wet-wall yield: 4 wet rotations vs 0 dry at y=33']), 0)
assert.equal(wetWallYields(['F6 [F6] climb wet-wall yield:4 wet rotations vs 0 dry']), 0)
assert.equal(wetWallYields(['F6 [F6] climb wet-wall yield 4 wet rotations vs 0 dry at y=33']), 0)

// the defensive reads
assert.equal(wetWallYields(null), 0)
assert.equal(wetWallYields(undefined), 0)
assert.equal(wetWallYields('junk'), 0)
assert.equal(wetWallYields(42), 0)
assert.equal(wetWallYields([null, 42, {}]), 0)

// THE ONE-PARSER RIDE - the fold rides the read's own arithmetic
const lines = [
  'F9 [F9] climb wet-wall yield: 4 wet rotations vs 0 dry at y=33 - no dry bearing owns this column, the fence reserve returns to the chain',
  'F19 [F19] climb wet-wall yield: 4 wet rotations vs 0 dry at y=59 - no dry bearing owns this column, the fence reserve returns to the chain',
  'F12 [F12] climb wet-wall yield: 2 wet rotations vs 3 dry at y=45 - no dry bearing owns this column, the fence reserve returns to the chain',
  'F10 [F10] climb wet-wall yield: 1 wet rotations vs 2 dry at y=38 - no dry bearing owns this column, the fence reserve returns to the chain',
  'F13 [F13] climb wet-wall yield: 5 wet rotations vs 0 dry at y=52 - no dry bearing owns this column, the fence reserve returns to the chain'
]
assert.equal(wetWallYields(lines), 5)
const fold = { back: { wetWallYields: wetWallYields(lines) }, prev: { wetWallYields: 1 }, cur: { wetWallYields: 0 } }
assert.equal(wetWallYieldTrendRow(fold), FADE + '5 -> 1 (-4) -> 0 (-1)' + FADE_TAIL)

console.log('wetwallyieldtrend.test: all pins green')
